import math
from itertools import permutations

def get_divisors(m):
    divs = set()
    for i in range(1, int(math.sqrt(m)) + 1):
        if m % i == 0:
            divs.add(i)
            divs.add(m // i)
    return sorted(list(divs))

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_m(m):
    divisors = get_divisors(m)
    n = len(divisors)

    # Optimization: Check the necessary condition first: sigma(m) must be a square
    sigma_m = sum(divisors)
    if not is_perfect_square(sigma_m):
        # This should already be filtered out by the candidate list, but good for safety
        return False, f"Sigma({m}) = {sigma_m} is not a perfect square."

    # Optimization: The first term a_1 must be a square divisor
    square_divisors = [d for d in divisors if is_perfect_square(d)]

    if not square_divisors:
        return False, "No square divisor exists for a_1."

    # Brute force permutation check
    for a1 in square_divisors:
        remaining_divs = [d for d in divisors if d != a1]

        # Check permutations starting with a1
        for perm in permutations(remaining_divs):
            permutation = (a1,) + perm

            current_sum = 0
            is_valid = True

            for i in range(n):
                a_i = permutation[i]
                current_sum += a_i

                if not is_perfect_square(current_sum):
                    is_valid = False
                    break

            if is_valid:
                return True, f"Found valid permutation: {permutation}"

    return False, "No valid permutation found."

# Candidates to test
candidates = [66, 70, 81, 94]
results = {}

for m in candidates:
    works, message = check_m(m)
    results[m] = (works, message)

print(results)
